"cresuz-village-play":{"rev":"3f4a79ae25734a2dad74ddf0544721e5fa5a861d664412f845232a64c3053a13","strings":{"name":"Crésuz · Spielplatz bei der Kirche","intro":"Dorfspielplatz mit Bänken, einem Tisch und einem nahen Hirschpark.","age":"Altersgrenzen nicht veröffentlicht","schedule":"Angaben aus einer Touristenliste von 2020; prüfen Sie die aktuellen Öffnungszeiten und den Zugang vor der Anreise","price":"Preis nicht veröffentlicht","address":"Centre du village, près de l’église, 1653 Crésuz","notes[0]":"Dorfspielplatz mit Bänken, einem Tisch und einem nahen Hirschpark.","notes[1]":"Beschreibung und Ausstattung beruhen auf einem Dokument von 2020; vor einem Besuch ist eine aktuelle Prüfung nötig.","practical.indoor.text":"Touristenliste vom 22.06.2020: Dorfspielplatz mit Bänken, einem Tisch und einem nahen Hirschpark.","practical.playArea.text":"Die Gemeinde Crésuz erwähnt einen Spielplatz im Dorfzentrum.","practical.warnings[0]":"Klären Sie, ob der Spielplatz besteht und der Hirschpark zugänglich ist; das Wasser im Brunnen ist als nicht trinkbar gekennzeichnet.","research.findings[0].field":"Verfügbarkeit und Format","research.findings[0].text":"Touristenliste vom 22.06.2020: Dorfspielplatz mit Bänken, einem Tisch und einem nahen Hirschpark.","research.findings[1].field":"Lage des Spielplatzes","research.findings[1].text":"Die Gemeinde Crésuz nennt einen Spielplatz im Zentrum des Dorfes. Die Seite gibt keine Eingangsadresse, Öffnungszeiten, Altersangaben oder keinen Preis an.","research.remaining[0]":"Klären Sie, ob der Spielplatz besteht und der Hirschpark zugänglich ist; das Wasser im Brunnen ist als nicht trinkbar gekennzeichnet.","research.remaining[1]":"Wie sind die Öffnungszeiten, und gibt es für den Spielplatz eine Altersspanne?","research.remaining[2]":"Ist der Spielplatz kostenlos nutzbar?","research.remaining[3]":"Gibt es für den Spielplatz im Dorfzentrum eine genaue Adresse oder einen bestimmten Eingang?","contacts[0].name":"La Gruyère Tourisme","sources[0].label":"Touristenliste der Picknickplätze, 22.06.2020","sources[1].label":"Zusätzliche Prüfung: Lage des Spielplatzes"}},
