"cugy-forest-play":{"rev":"29e9a332a627b29898e3d377db157840d4650cb66777fca156085b6a91b18a69","strings":{"name":"Waldspielplatz Cugy · Picknick","intro":"Das Tourismusbüro bestätigt in Cugy einen Waldunterstand, eine Feuerstelle und einen Spielbereich für Kinder; laut seinen Angaben wird der Unterstand über die Gemeinde reserviert.","age":"Altersgrenzen nicht veröffentlicht","schedule":"Waldgelände; Zugang zum Unterstand nach Absprache","price":"Preis nicht veröffentlicht","address":"Forêt de Cugy, 1482 Cugy FR","notes[0]":"Spielbereich und Picknick im Wald; der Unterstand sollte ohne Anmeldung nicht als frei zugänglich betrachtet werden.","notes[1]":"Klären Sie, ob der Spielbereich ohne Reservation und unabhängig vom Unterstand genutzt werden kann; die Aufsicht über das Kind bleibt bei der erwachsenen Person.","practical.indoor.text":"Das Tourismusbüro bestätigt in Cugy einen Waldunterstand, eine Feuerstelle und einen Spielbereich für Kinder; laut seinen Angaben wird der Unterstand über die Gemeinde reserviert.","practical.warnings[0]":"Der genaue Standort, das Alter der Geräte und ob die Anmeldepflicht auch für den offenen Spielbereich gilt, sind nicht beschrieben.","research.findings[0].field":"Verfügbarkeit und Format","research.findings[0].text":"Das Tourismusbüro bestätigt in Cugy einen Waldunterstand, eine Feuerstelle und einen Spielbereich für Kinder; laut seinen Angaben wird der Unterstand über die Gemeinde reserviert.","research.remaining[0]":"Der genaue Standort, das Alter der Geräte und ob die Anmeldepflicht auch für den offenen Spielbereich gilt, sind nicht beschrieben.","contacts[0].name":"Commune de Cugy","sources[0].label":"Tourismus: Spielbereich, Feuerstelle, Unterstand und Anmeldepflicht"}},
"danse-turin":{"rev":"4f23a93538ea63d89980a3db92e3ee8b1dacfc31fe1ed2e25618618463e47f59","strings":{"name":"Danse parent-enfant · FDance Fitness","age":"2–4 Jahre","schedule":"Dienstag 09:15–10:15","price":"CHF 540 / September–Juni / Paar aus erwachsener Person und Kind","address":"FDance Fitness, Route de Chésalles 7, Marly","notes[0]":"Mit einem zweiten Kind betragen die Gesamtkosten für September–Juni CHF 720.","notes[1]":"Fragen Sie nach freien Plätzen und einem Schnuppertermin.","research.findings[0].field":"Leitung","research.findings[0].text":"Die Leitung beschreibt eine Tanzausbildung in Huy und Brüssel, Alvin-Ailey-Intensivkurse in New York und eine Ausbildung zur Kindergartenlehrperson an einer Rudolf-Steiner-Einrichtung in Bern. Dies ist die eigene Biografie der Leitung; sie bestätigt keinen Universitätsabschluss in Kinderpsychologie.","research.findings[1].field":"Teilnahme und Kleidung","research.findings[1].text":"Die erwachsene Person tanzt gemeinsam mit dem Kind: Lieder mit Bewegungen, Spiele und einfache Tänze. Bequeme Kleidung, Ballettschuhe oder rutschfeste Socken und zusammengebundene Haare sind erforderlich. CHF 540 für das Schuljahr gelten für das Paar; mit einem zweiten Kind aus derselben Familie betragen die Gesamtkosten CHF 720.","research.remaining[0]":"Die Kosten für einen Schnuppertermin, die Verfügbarkeit von Plätzen, die Möglichkeit eines Einstiegs nach September und die Sprache des konkreten Termins.","sources[0].label":"Offizielle Quelle","sources[1].label":"Leitung"}},
"defenant-grangettes":{"rev":"af94697df359cccc48536a683423542d2ded904189011dca937fd34027077fc3","strings":{"name":"Buvette du Défénant · Spielplatz auf der Alp","intro":"Eine kleine Berg-Buvette mit Spielplatz; prüfen Sie vor dem Ausflug, ob sie geöffnet ist.","age":"Altersgrenzen sind nicht veröffentlicht.","schedule":"Öffnungszeiten und Saison 2026 sind nicht veröffentlicht; prüfen Sie vor der Reise.","price":"Der Preis ist nicht veröffentlicht.","address":"Route du Défénant 5, 1686 Grangettes-près-Romont","notes[0]":"Bergküche: Speisen und Getränke werden separat bezahlt; eine Preisliste ist nicht veröffentlicht.","notes[1]":"Der Spielplatz ist ohne Beschreibung seiner Geräte aufgeführt und ohne Angabe, ob er von der Terrasse aus sichtbar ist; kleine Kinder brauchen Aufsicht.","notes[2]":"Die Tourismusseite nennt Route du Défénant 5; die Broschüre 2026 nennt Route de Romanens 5. Die Broschüre gibt an, dass am Dienstag geschlossen ist; prüfen Sie die Adresse und die Öffnungszeiten vor dem Ausflug.","practical.indoor.text":"Die Tourismusseite beschreibt eine Alp-Buvette mit Kinderspielplatz, 20 Sitzplätzen drinnen und 30 auf der Terrasse.","practical.warnings[0]":"Die aktuelle Saison, die Öffnungszeiten, die Preise auf der Speisekarte und die Zugangsbedingungen zum Spielplatz sind nicht veröffentlicht; die Adresse unterscheidet sich je nach Quelle.","research.findings[0].field":"Verfügbarkeit und Format","research.findings[0].text":"Die Tourismusseite beschreibt eine Alp-Buvette mit Kinderspielplatz, 20 Sitzplätzen drinnen und 30 auf der Terrasse.","research.remaining[0]":"Die aktuelle Saison, die Öffnungszeiten, die Preise auf der Speisekarte und die Zugangsbedingungen zum Spielplatz sind nicht veröffentlicht; die Adresse unterscheidet sich je nach Quelle.","sources[0].label":"Tourismus: Spielplatz, Adresse und Kontakt","sources[1].label":"Broschüre 2026: andere Adresse und dienstags geschlossen"}},
"devenir-famille-fribourg-2026-10-03":{"rev":"ef7b90a3a45818edfd5b8257018687aa1fc070e7af1d87d2bcb6afeb9336b0b5","strings":{"name":"Devenir famille · Familie werden","intro":"Eltern sprechen mit einer Hebamme, einer Fachperson für frühe Kindheit und einer Mitarbeitenden- oder Mitarbeiterperson der Familienbegleitung. Kinder können kommen, aber es ist keine Aktivität für Kinder angekündigt.","parentDetails":"Ein Treffen für Eltern und werdende Eltern. Babys und andere Kinder können die Erwachsenen begleiten.","age":"Für Eltern von kleinen Kindern; andere Kinder können mitkommen","schedule":"3. Oktober 2026 · 09:30–11:30","price":"Kostenlos, ohne Anmeldung","address":"Rue de l’Hôpital 2, Fribourg","notes[0]":"Der Eingang zum Bureau familles et école befindet sich an der rue du Criblet, im Erdgeschoss desselben Gebäudes. Die Adressmarkierung zeigt das Gebäude, nicht diesen Eingang.","notes[1]":"Der Name und die Seite sind zweisprachig. Die Sprache der Diskussion in einer bestimmten Gruppe ist nicht bestätigt.","practical.indoor.text":"Drinnen im Bureau familles et école","practical.access.text":"Erdgeschoss, Eingang von der rue du Criblet; der Zugang mit Kinderwagen ist nicht separat beschrieben","practical.booking.text":"Keine Anmeldung","practical.duration.text":"09:30–11:30","research.findings[0].field":"Datum und Ort","research.findings[0].text":"Das Treffen findet am 3. Oktober von 09:30 bis 11:30 im Bureau familles et école statt. Der Eingang befindet sich an der rue du Criblet, im Erdgeschoss.","research.findings[1].field":"Format","research.findings[1].text":"Eltern besprechen ihre Fragen mit einer Hebamme, einer Fachperson für frühe Kindheit und einer Vertretung der Familienbegleitung (AEF). Auch andere Kinder können kommen.","research.findings[2].field":"Preis und Anmeldung","research.findings[2].text":"Der Anbieter gibt an, dass die Treffen kostenlos sind und keine Anmeldung erfordern.","research.findings[3].field":"Datum","research.findings[3].text":"Das Stadtprogramm nennt Samstag, 3. Oktober 2026 als Datum dieses Treffens. Dieses Datum ist nun vorbei, daher ist dieses Treffen beendet.","research.remaining[0]":"In welcher Sprache wird die Diskussion am 3. Oktober konkret geführt?","research.remaining[1]":"Gibt es einen Spielbereich für ein begleitendes Kind?","research.remaining[2]":"Finden weitere Treffen an anderen Terminen im Bureau familles et école statt?","sources[0].label":"Stadtprogramm: Datum, Zutritt und Format","sources[1].label":"Anbieter: Teilnahmebedingungen"}},
