"drachenland":{"rev":"c811153e4d7068f2e32c13e4f065cea1bac4169e52e9ee1cc8cdceebc75fe6b8","strings":{"name":"Drachenland auf der Riggisalp","age":"Kein Mindestalter angegeben; einige Elemente sind für ältere Kinder","schedule":"14.05–01.11.2026 · Mo–Fr 08:30–17:00; Sa–So 08:00–17:00","price":"Bahn CHF 21 Hin- und Rückfahrt / erwachsene Person von 25 bis 63 Jahren; bis 6 noch nicht bestätigt","address":"Riggisalp, Schwarzsee","notes[0]":"Sandkasten, Rutschen und Balancierbalken bei der Bergstation.","notes[1]":"Sesselbahn, keine geschlossene Kabine. Klären Sie die Mitnahme von kleinen Kindern und Kinderwagen; der Betrieb hängt von den Bedingungen ab.","research.findings[0].field":"Vor Ort","research.findings[0].text":"Auf Riggisalp sind ein Sandkasten, Rutschen, Balancierbalken, eine Spielseilbahn und Kugelbahnen aufgeführt; es gibt Tische und einen Grillplatz.","research.findings[1].field":"Bahn","research.findings[1].text":"Tarif 2026 für eine erwachsene Person von 25 bis 63 Jahren: CHF 21 Hin- und Rückfahrt, CHF 16 einfache Fahrt. Kindertarif für 6–15 Jahre: CHF 12 Hin- und Rückfahrt.","research.findings[2].field":"Saison","research.findings[2].text":"Der Sommerfahrplan der Bahn gilt vom 14. Mai bis 1. November 2026; der tatsächliche Betrieb hängt von den Bedingungen ab.","research.remaining[0]":"Noch nicht bestätigt: ob kleine Kinder auf der Sesselbahn zugelassen sind, die Mitnahme von Kinderwagen, der Tarif bis 6 und geeignete Ausrüstung.","contacts[0].name":"Kaisereggbahnen","sources[0].label":"Offizielle Quelle","sources[1].label":"Tarife","sources[2].label":"Öffnungszeiten"}},
"echarlens-legendes":{"rev":"9b72433176d46c69805d4e13a7138bc6e47305cf614b575f1ac37f991cb5a1f4","strings":{"name":"Au pays des Légendes · kurze Runde","intro":"Das Tourismusbüro beschreibt mehr als 20 illustrierte Legenden und eine kurze Runde von etwa 3 km ab Echarlens; die gesamte Route ist etwa 6 km lang.","age":"Altersgrenzen sind nicht veröffentlicht.","schedule":"Offener Waldweg, bei geeignetem Wetter.","price":"Preis nicht veröffentlicht.","address":"Départ Echarlens, 1646 Echarlens","notes[0]":"Wählen Sie mit kleinen Kindern die kurze Runde statt der Option mit sechs Kilometern; die Dauer hängt von den Pausen ab.","notes[1]":"Die Route führt über Waldwege, festes Schuhwerk wird empfohlen; Altersgrenzen und Eintrittspreis sind nicht veröffentlicht.","practical.indoor.text":"Das Tourismusbüro beschreibt mehr als 20 illustrierte Legenden und eine kurze Runde von etwa 3 km ab Echarlens; die gesamte Route ist etwa 6 km lang.","practical.warnings[0]":"Die genaue Startadresse, der Zustand des Wegs und der Zugang mit Kinderwagen sind nicht bestätigt.","research.findings[0].field":"Verfügbarkeit und Format","research.findings[0].text":"Das Tourismusbüro beschreibt mehr als 20 illustrierte Legenden und eine kurze Runde von etwa 3 km ab Echarlens; die gesamte Route ist etwa 6 km lang.","research.findings[1].field":"Routenoptionen","research.findings[1].text":"Das Tourismusbüro führt drei Routenoptionen auf: eine lange Route von etwa 6 km, eine Runde von etwa 3 km ab Echarlens oder Vuippens und eine zweite Runde von etwa 3 km ab Vuippens. Es empfiehlt gutes Schuhwerk.","research.remaining[0]":"Die genaue Startadresse, der Zustand des Wegs und der Zugang mit Kinderwagen sind nicht bestätigt.","research.remaining[1]":"Wird erwartet, dass eine erwachsene Person kleine Kinder begleitet, und gibt es ein empfohlenes Mindestalter? Die Seite des Tourismusbüros sagt dazu nichts.","contacts[0].name":"Société de Développement du Lac de La Gruyère","sources[0].label":"Tourismus: illustrierte Legenden, Routenoptionen und Karte"}},
