"murten-family-pool":{"rev":"e0c7480ccc9665f4cc2a5e2855b9e207370cb008384c55fe55bf26d30c997634","strings":{"name":"Piscine de Morat · Familienschwimmen","intro":"Hallenbad für selbstständige Besuche mit einem Kind; das Spielbecken ist ohne Tiefenangabe aufgeführt.","age":"Altersgrenzen sind nicht veröffentlicht","schedule":"Mo 14:00–21:00; Di 06:00–21:00; Mi–Fr 09:30–21:00; Sa–So 09:30–18:00","price":"Erwachsene CHF 8; Studierende, Lernende, AHV/IV CHF 7; Kinder im Alter von 6–15 Jahren CHF 5. Die regionale Seite nennt weder Einheit noch Zeitraum und führt keinen Preis für Kinder unter 6 Jahren auf.","address":"Lausannestrasse 2, 3280 Murten","notes[0]":"Dies ist ein gewöhnlicher Familienbesuch ohne Kursleitung, getrennt von den Kursen Baby Bade-Plausch und First Flow.","notes[1]":"Der Strand, der Aussenbereich und das Café sind saisonal; die Öffnungszeiten des Hallenbads garantieren nicht, dass sie geöffnet sind.","practical.indoor.text":"Das Hallenbad in Murten ist ganzjährig geöffnet; die Tourismusseite beschreibt ein warmes Spielbecken.","practical.warnings[0]":"Die Tiefe des Spielbeckens und das Ticket für ein Kind unter sechs Jahren sind nicht angegeben.","research.findings[0].field":"Verfügbarkeit und Format","research.findings[0].text":"Das Hallenbad in Murten ist ganzjährig geöffnet; die Tourismusseite beschreibt ein warmes Spielbecken.","research.findings[1].field":"Preis","research.findings[1].text":"Die regionale Seite nennt Erwachsene CHF 8, Studierende, Lernende und AHV/IV-Berechtigte CHF 7 sowie Kinder im Alter von 6–15 Jahren CHF 5. Sie nennt weder Einheit noch Zeitraum und keinen Preis für Kinder unter 6 Jahren, daher fällt ein sechsjähriges Kind unter den Kindertarif für 6–15 Jahre.","research.remaining[0]":"Die Tiefe des Spielbeckens und das Ticket für ein Kind unter sechs Jahren sind nicht angegeben.","research.remaining[1]":"Gilt der Eintrittspreis pro Besuch oder pro Zeitraum, und was zahlt ein Kind unter 6 Jahren?","contacts[0].name":"Schwimmbad Murten","sources[0].label":"Bad, Familienbereich, Adresse, Öffnungszeiten und Tarif"}},
"musee-grenouilles-estavayer":{"rev":"6191417af8244e5abfccf08c45c2e4249a46dde6491f6e3e742a8fd404353f24","strings":{"name":"Musée des Grenouilles · Familienbesuch","intro":"Ein kleines Museum mit der Geschichte von Estavayer und einer ungewöhnlichen Sammlung von Fröschen.","parentDetails":"Das Kind besucht das Museum mit einer erwachsenen Person.","age":"Familienmuseum; Kindertarif, Mindestalter nicht angegeben","schedule":"März–Dezember: Di–So 13–18; geschlossen Januar–Februar","price":"Erwachsene CHF 5; Kind CHF 3 (Mindestalter nicht angegeben)","address":"Rue du Musée 13, 1470 Estavayer-le-Lac","notes[0]":"Ein bekannter Teil der Ausstellung sind Szenen mit präparierten Fröschen. Wenn Ihr Kind empfindlich ist, sehen Sie sich den Inhalt vorher an.","notes[1]":"Geschlossen im Januar–Februar sowie am 25., 26. und 31. Dezember.","notes[2]":"Dies ist ein Museumsbesuch, kein Workshop für Kinder.","practical.indoor.text":"Museum in Innenräumen","practical.warnings[0]":"Die Ausstellung enthält präparierte Tiere; prüfen Sie, ob das für Ihr Kind geeignet ist","practical.warnings[1]":"Geschlossen im Januar und Februar","research.findings[0].field":"Ausstellung","research.findings[0].text":"Zu den Exponaten gehören Szenen aus präparierten Fröschen; Eintritt Erwachsene CHF 5, Kind CHF 3.","research.remaining[0]":"Das Mindestalter für das Kinderticket ist nicht angegeben; eine Familie mit einem empfindlichen Kind sollte die Ausstellung vorher beurteilen.","contacts[0].name":"Musée d’Estavayer","sources[0].label":"Ausstellung, Tarif, Öffnungszeiten und Kontakt"}},
"museum":{"rev":"08e5764983b73b62a5adf1f1a5a287bfea8a34cebc8731a620abea93593fb897","strings":{"name":"Musée d’histoire naturelle · Familienworkshops","intro":"Workshops am Samstagvormittag, in denen Eltern und Kinder die Naturwissenschaften durch Spiele, Experimente und Erklärungen entdecken, geleitet von Vermittlungspersonen des Museums und Mitarbeitenden der Association pour l'Éducation Familiale.","age":"Empfohlen für Kinder von 3–7 Jahren; jüngere und ältere Kinder sind zugelassen","schedule":"Samstags, 9:30–10:30 oder 10:45–11:45 (seien Sie pünktlich an der Museumsrezeption); Programm September 2026 – Februar 2027","price":"Kostenlos","address":"Chemin du Musée 6, 1700 Fribourg","events[0].title":"Brico-Baleine","events[1].title":"C'est quoi grandir ?","events[2].title":"Poils et mamelles","events[3].title":"Boules de feu","events[4].title":"Lièvre ou lapin ?","events[5].title":"À qui est ce cri ?","notes[0]":"Jedes Workshop-Datum bietet zwei einstündige Termine; das Programm gibt nicht an, welches Zeitfenster für welches Datum gilt. Anmeldung ist telefonisch erforderlich. Prüfen Sie die Sprache des jeweiligen Termins.","practical.indoor.text":"Treffpunkt im Museum","practical.booking.text":"Anmeldung telefonisch unter 026 305 89 00","practical.duration.text":"Ein Termin, 60 Minuten","practical.commitment.text":"Einzelne kostenlose Termine","practical.costNote.text":"Als kostenlos aufgeführt; die Seite nennt keine weiteren Kosten für den Workshop.","research.findings[0].field":"Für kleine Kinder","research.findings[0].text":"Empfohlen ist ein Alter von 3–7 Jahren, jüngere und ältere Kinder sind aber ausdrücklich zugelassen. Die Aktivitäten werden von Vermittlungspersonen des Museums zusammen mit Fachpersonen der AEF geleitet. Kostenlos, Anmeldung unter 026 305 89 00; Treffpunkt an der Rezeption genau zu Beginn des gewählten Termins.","research.findings[1].field":"Anlässe","research.findings[1].text":"Das Programm September 2026 – Februar 2027 führt sechs Samstags-Workshops auf: 12. Sept., 3. Okt., 7. Nov., 12. Dez. 2026, 23. Jan. und 27. Feb. 2027. Jeder Tag hat zwei einstündige Zeitfenster (9:30–10:30 oder 10:45–11:45), und die Seite gibt nicht an, welches Zeitfenster für welches Datum gilt.","research.findings[2].field":"Nächster Workshop","research.findings[2].text":"Der nächste aufgeführte Workshop ist «Poils et mamelles» am 7. November 2026, über das Kennenlernen von Säugetieren. Jeder Samstagstermin beginnt um 9:30 oder 10:45 an der Museumsrezeption, und die Familien werden gebeten, pünktlich zu kommen.","research.remaining[0]":"Freie Plätze, Sprache und die Möglichkeit, früher zu gehen: bei der Anmeldung zu besprechen.","research.remaining[1]":"Welches Zeitfenster (9:30 oder 10:45) wird an welchem Workshop-Datum angeboten, und in welcher Sprache findet der Termin statt? Familien sollten bei der Anmeldung nachfragen.","research.remaining[2]":"Gibt es Parkplätze, einen Wickeltisch, ein WC oder einen kinderwagengängigen Zugang für den Workshop? Die Seite sagt dazu nichts.","research.remaining[3]":"Welche der beiden Startzeiten (9:30 oder 10:45) gilt am 7. November 2026? Familien sollten bei der Anmeldung nachfragen.","contacts[0].name":"Musée d’histoire naturelle de Fribourg","sources[0].label":"Offizielle Quelle"}},
