"ondena":{"rev":"40f51d78b312e2dec341f933439fdf17ad65ffa06482e3fd7af6219cb890f23d","strings":{"name":"Au fil de l’Ondena · Petit Pois","age":"0–6 Jahre","schedule":"Samstags 09:30–11:30. Veröffentlichte Daten: 19. Sep, 3. Okt und 10. Okt 2026, dann 13. und 20. Mär, 17. und 24. Apr, 15. und 22. Mai, 12. und 19. Jun 2027. Zwischen dem 10. Okt 2026 und dem 13. Mär 2027 sind keine Daten veröffentlicht.","price":"Ab CHF 50; prüfen Sie, welche Familienzusammensetzung im Tarif enthalten ist","address":"Route de Montécu 94, 1724 Bonnefontaine","notes[0]":"Workshops für Eltern und Kinder von 0–6 Jahren: Füttern und Pflegen der Hoftiere, ein Imbiss, eine Sinnesgeschichte, Basteln mit Naturmaterialien und Spiele im Freien. Die veröffentlichten Daten reichen bis zum 19. Juni 2027, zwischen dem 10. Oktober 2026 und dem 13. März 2027 sind keine aufgeführt.","notes[1]":"Ein Umweg von der direkten Route. Nicht zu verwechseln mit Haricot 4–13.","research.findings[0].field":"Team","research.findings[0].text":"Die Teamseite nennt drei Mitarbeitende; eine Person davon ist auch für Projekte zuständig. Der Verein gibt Erfahrung in Heilpädagogik, Natur und Arbeit mit Tieren an, einzelne Qualifikationen und die Leitung eines bestimmten Termins werden jedoch nicht bekannt gegeben.","research.findings[1].field":"Zeiten und Programm","research.findings[1].text":"Die offizielle Seite führt Samstagstermine von 09:30 bis 11:30 auf: 19. September, 3. Oktober und 10. Oktober 2026, dann 13. März, 20. März, 17. April, 24. April, 15. Mai, 22. Mai, 12. Juni und 19. Juni 2027 (insgesamt 11 Daten). Die Teilnahme ist nur mit Anmeldung möglich. Das Programm für Eltern und Kinder von 0–6 Jahren umfasst das Füttern und Pflegen der Tiere, einen Imbiss, eine Sinnesgeschichte, Basteln mit Naturmaterialien und Spiele im Freien.","research.remaining[0]":"Ist eine erwachsene Person im Preis ab CHF 50 inbegriffen?","research.remaining[1]":"Wie sieht der Plan bei Regen aus?","research.remaining[2]":"Gibt es ein WC für Besucherinnen und Besucher?","research.remaining[3]":"Können die Kinder Abstand zu den Tieren halten?","research.remaining[4]":"Finden zwischen dem 10. Oktober 2026 und dem 13. März 2027 Termine statt?","contacts[0].name":"Au fil de l’Ondena","sources[0].label":"Offizielle Quelle","sources[1].label":"Anmeldung und Preise","sources[2].label":"Zusätzliche Prüfung: Team"}},
"onnens-school-park":{"rev":"29d42d61799b94596145bca67da41107b1a2925fc4712f036f040333b74e4f39","strings":{"name":"Parc de l’école d’Onnens","intro":"Der regionale Verband beschreibt einen Park für mehrere Generationen mit Geräten für Kleinkinder und Zugang für Kinderwagen. Die Gemeinde meldete eine Renovation im Jahr 2025.","age":"Altersgrenzen sind nicht veröffentlicht.","schedule":"Die Zugangszeiten für die Öffentlichkeit sind nicht angegeben.","price":"Preis nicht veröffentlicht.","address":"École d’Onnens, 1756 Onnens; Eingang noch nicht bestätigt","notes[0]":"Während der Schulzeit haben Schulkinder möglicherweise Vorrang. Prüfen Sie vor dem Besuch die Regeln vor Ort.","notes[1]":"Bushaltestelle Onnens FR, Eglise. Parkplätze sind vom regionalen Verband aufgeführt.","practical.indoor.text":"Der regionale Verband beschreibt einen Park für mehrere Generationen mit Geräten für Kleinkinder und Zugang für Kinderwagen. Die Gemeinde meldete eine Renovation im Jahr 2025.","practical.warnings[0]":"Es ist nicht veröffentlicht, ob der Zugang während des Schulunterrichts eingeschränkt ist oder wo sich der genaue Eingang befindet.","research.findings[0].field":"Verfügbarkeit und Format","research.findings[0].text":"Der regionale Verband beschreibt einen Park für mehrere Generationen mit Geräten für Kleinkinder und Zugang für Kinderwagen. Die Gemeinde meldete eine Renovation im Jahr 2025.","research.remaining[0]":"Es ist nicht veröffentlicht, ob der Zugang während des Schulunterrichts eingeschränkt ist oder wo sich der genaue Eingang befindet.","contacts[0].name":"Commune de La Brillaz","sources[0].label":"Regionalverband Sarine: Spielplatz für Kleinkinder und Zugang","sources[1].label":"Gemeinde: Renovation des Spielplatzes 2025"}},
"paccots-recreation":{"rev":"660d3b872b39c2d3eba838d17a3898151cda3bbab7d753f696412b084fde6547","strings":{"name":"Zone récréative des Paccots · teilweise geöffnet","intro":"Die Anlage wird renoviert. Mehrere Elemente sind zugänglich, die neue Ausstattung ist aber noch nicht geöffnet.","age":"Altersgrenzen nicht veröffentlicht","schedule":"Renovation ab 17.08.2026 für etwa zwei Monate; nur ein Teil der Anlage ist zugänglich","price":"Preis nicht veröffentlicht","address":"Route des Dailles, 1619 Les Paccots","notes[0]":"Während der Arbeiten sind ein Unterstand, ein Kiesweg, Schaukeln, ein Aussichtsturm, ein Tisch und eine Seilbahn aufgeführt. Die neuen Wasserspiele sind noch nicht bestätigt.","notes[1]":"Prüfen Sie wegen der teilweisen Schliessung vor dem Besuch die Ankündigung zur Öffnung.","practical.indoor.text":"Während der Renovation hält das Tourismusbüro den oberen und den unteren Teil der Anlage als zwei getrennte Bereiche offen.","practical.warnings[0]":"Das Enddatum der Renovation und die tatsächliche Verfügbarkeit an einem bestimmten Tag sind nicht bestätigt.","research.findings[0].field":"Verfügbarkeit und Format","research.findings[0].text":"Während der Renovation hält das Tourismusbüro den oberen und den unteren Teil der Anlage als zwei getrennte Bereiche offen.","research.remaining[0]":"Das Enddatum der Renovation und die tatsächliche Verfügbarkeit an einem bestimmten Tag sind nicht bestätigt.","contacts[0].name":"Les Paccots Tourisme","sources[0].label":"Renovation und der zugängliche Teil der Anlage"}},
