"papier-peint-mezieres":{"rev":"56cf623bb16470ddaa51ab5c804c1408d33fff73e620a9a94a8a065d9a205d70","strings":{"name":"Musée du papier peint · Rätsel für Kinder","intro":"Ein Museum mit Rätseln zur Ausstellung und separaten kreativen Workshops.","age":"Altersgrenzen sind nicht veröffentlicht","schedule":"Bis 31.10. Do–So 13:30–17:00; im Winter Sa–So 13:30–17:00","price":"Erwachsene CHF 8; Kinderticket, 6–16 Jahre, CHF 4; unter 6 Jahren: noch nicht bestätigt","address":"Rue de l’Église 12, 1684 Mézières","notes[0]":"Die Rätsel werden mit Fragebögen gelöst, daher ist es für kleine Kinder vor allem eine gemeinsame Entdeckungstour mit einem Elternteil.","notes[1]":"Der Workshop ist nicht automatisch im Museumsticket enthalten; die Bedingungen müssen separat vereinbart werden.","practical.indoor.text":"Das Museum bietet Rätsel für jeden Raum; kreative Workshops finden separat auf Anmeldung statt.","practical.warnings[0]":"Das Mindestalter für die Rätsel, aktuelle Workshop-Termine und der Ticketpreis für ein Kind unter sechs Jahren sind nicht veröffentlicht.","research.findings[0].field":"Verfügbarkeit und Format","research.findings[0].text":"Das Museum bietet Rätsel für jeden Raum; kreative Workshops finden separat auf Anmeldung statt.","research.remaining[0]":"Das Mindestalter für die Rätsel, aktuelle Workshop-Termine und der Ticketpreis für ein Kind unter sechs Jahren sind nicht veröffentlicht.","contacts[0].name":"Musée du papier peint","sources[0].label":"Aktivitäten für Kinder und Adresse","sources[1].label":"Öffnungszeiten und Preise"}},
"papiliorama-kerzers":{"rev":"3827ae08e9454803006cfcacb234c6f436cd4f3e1efec1b9450237ac8aea1537","strings":{"name":"Papiliorama · Familienbesuch","parentDetails":"Kinder besuchen die Ausstellungen in Begleitung einer erwachsenen Person.","age":"Bis und mit 3 Jahren gratis; Kinder bis 15 Jahre mit einer erwachsenen Person","schedule":"Bis 24.10: 09:00–18:00; ab 25.10 bis 17:00, Öffnungszeit noch nicht bestätigt","price":"Erwachsene CHF 22; 4–15 Jahre CHF 12; bis und mit 3 Jahren gratis","address":"Moosmatte 1, 3210 Kerzers","notes[0]":"Im Sommer ist der letzte Einlass um 17:15; ab 25. Oktober um 16:15. Prüfen Sie vor dem Besuch die Zeiten auf Ausnahmen.","practical.photo.alt":"Papiliorama-Kuppeln, Aussenansicht im Oktober 2010","practical.photo.caption":"Aussenansicht, 7. Oktober 2010. Historisches Foto: Es bestätigt weder den aktuellen Eingang noch den Spielbereich.","research.findings[0].field":"Tickets und Besuch","research.findings[0].text":"Tageskarten werden vor Ort verkauft, nicht online. Kinder bis und mit 3 Jahren gratis, 4–15 Jahre CHF 12, Erwachsene CHF 22. Parkplätze kosten CHF 4 pro Tag; die Haltestelle Kerzers Papiliorama ist 80 m entfernt. Picknick ist in ausgewiesenen Bereichen erlaubt.","research.findings[1].field":"Bedingungen im Innenbereich","research.findings[1].text":"Die Tropenhallen haben rund 25 °C und sind feucht; Schliessfächer sind mit CHF 1 Pfand verfügbar. Nocturama öffnet um 10:00. Geschlossen am 25. Dezember und 1. Januar.","research.findings[2].field":"Abweichung bei den Zeiten","research.findings[2].text":"Die Hauptseite nennt 09:00–17:00 ab 25.10.2026; die FAQ nennt im Winter eine Öffnung um 10:00. Die Öffnungszeit sollte vor einem Winterbesuch bestätigt werden.","research.remaining[0]":"Die Öffnungszeit im Winter ist noch zu klären: Die Seiten weichen voneinander ab. Die Verfügbarkeit eines Wickeltischs und eine Route mit Kinderwagen sind nicht separat bestätigt.","contacts[0].name":"Papiliorama","sources[0].label":"Offizielle Seite: Zeiten, Preise und Begleitung","sources[1].label":"Bedingungen im Innenbereich"}},
