"plage-cheyres":{"rev":"842db867b1e0c563694d1e2eb3bab281da84e4f33054732851feddc20e8617fc","strings":{"name":"Plage de Cheyres · Ort am See","intro":"Schattiger Strand mit Spielplatz und Picknickbereich.","parentDetails":"Eine erwachsene Person bleibt jederzeit mit dem Kind am Wasser.","age":"Familienstrand; der Altersbereich der Geräte ist nicht angegeben","schedule":"Öffentlicher Strand; die Verfügbarkeit der Angebote hängt von der Saison ab","price":"Preis nicht veröffentlicht","address":"Route du Port, 1468 Cheyres-Châbles","notes[0]":"Sand und schattige Wiese, Spielplatz, WC, Dusche, Picknickbereich und Restaurant.","notes[1]":"Der Bahnhof Cheyres ist zu Fuss erreichbar. Der kostenpflichtige Parkplatz unterhalb des Bahnhofs, etwa acht Minuten zu Fuss vom Strand, ist von Mai bis September geöffnet.","notes[2]":"Der Eintrittspreis ist nicht veröffentlicht. Hunde sind von Mai bis September nicht erlaubt. Im Winter sind sie an der Leine erlaubt, aber nicht im Wasser.","practical.indoor.text":"Strand im Freien","practical.playArea.text":"Spielplatz","practical.toilet.text":"WC und Dusche","practical.parking.text":"Kostenpflichtige Parkplätze, etwa acht Minuten zu Fuss","research.findings[0].field":"Familieneinrichtungen","research.findings[0].text":"Es gibt einen Spielplatz, Sand, Schatten, WC und Dusche. Parkplätze sind kostenpflichtig und etwa acht Minuten zu Fuss entfernt.","research.remaining[0]":"Der Eintrittspreis und die Zeiten der saisonalen Angebote sind nicht veröffentlicht.","contacts[0].name":"Commune de Cheyres-Châbles","sources[0].label":"Spielbereich, Schatten, Angebote, Zugang und saisonale Regeln"}},
