"verslimorgen-duedingen":{"rev":"d8f784647c463ba7f7d7dc635c41e29c35fdaadaa7726260cb57b7ea1a0daba9","strings":{"name":"Verslimorgen · Bibliothek Düdingen","intro":"Ein Bookstart-Termin für Kinder bis 3 Jahre in Begleitung einer erwachsenen Person in der Schul- und Gemeindebibliothek in Düdingen.","parentDetails":"Das Kind kommt mit einer Begleitperson. Ob die erwachsene Person am Termin teilnehmen muss, ist nicht angegeben.","age":"Bis 3 Jahre","schedule":"An veröffentlichten Donnerstagen · 10:00–10:30","price":"Kostenlos","address":"Schul- und Gemeindebibliothek, Brunnenweg 16, 3186 Düdingen","events[0].title":"Verslimorgen","events[1].title":"Verslimorgen","notes[0]":"Das Kind kommt mit einer Begleitperson. Ob die erwachsene Person am Termin teilnehmen muss, ist nicht angegeben.","notes[1]":"Die Sprache des Termins ist nicht angegeben.","research.findings[0].field":"Teilnahme","research.findings[0].text":"Der Termin ist kostenlos, für Kinder bis 3 Jahre mit einer Begleitperson. Ob die erwachsene Person am Termin teilnehmen muss, ist nicht angegeben.","research.findings[1].field":"Zeiten","research.findings[1].text":"Die nächsten Termine sind am 5. November und 3. Dezember 2026, 10:00–10:30. Die Auflistung nennt einzelne Daten, keine wöchentlichen Termine.","research.findings[2].field":"Adresse","research.findings[2].text":"Die Termine finden in der Schul- und Gemeindebibliothek, Brunnenweg 16, 3186 Düdingen statt.","research.findings[3].field":"Zeiten und Eintritt","research.findings[3].text":"Die Auflistung der Bibliothek zeigt freien Eintritt und zwei Donnerstagstermine, 5. November und 3. Dezember 2026. Die Auflistung selbst nennt keine Anfangs- oder Endzeiten.","research.findings[4].field":"Daten und Eintritt","research.findings[4].text":"Das Buchstart-Register führt den Termin in Düdingen als kostenlos, für Kinder bis 3 Jahre mit einer Begleitperson, mit zwei Daten: Donnerstag, 5. November 2026 und Donnerstag, 3. Dezember 2026. Die Registerseite nennt keine Anfangs- oder Endzeiten.","research.remaining[0]":"Fragen Sie die Bibliothek, ob eine Anmeldung im Voraus nötig ist und ob man ruhig von der Seite zuschauen kann.","research.remaining[1]":"In welcher Sprache findet der Termin statt?","research.remaining[2]":"Muss die erwachsene Person am Termin teilnehmen?","research.remaining[3]":"Ab welchem Alter können Kinder teilnehmen?","research.remaining[4]":"Ist eine Anmeldung im Voraus nötig?","research.remaining[5]":"Kann man zuerst von der Seite zuschauen, ohne teilzunehmen?","research.remaining[6]":"Welche Anfangs- und Endzeiten gelten am 5. November und 3. Dezember 2026?","contacts[0].name":"Bibliothek Düdingen","sources[0].label":"Buchstart-Register: Düdingen","sources[1].label":"Auflistung der Bibliothek: Zeiten und Daten"}},
"village-lacustre-gletterens":{"rev":"a2516f4d5dc7938e9d108e71b561a0185dd5d4456fd51ab7ecec7640849dc91d","strings":{"name":"Village lacustre · prähistorische Siedlung","intro":"Rekonstruktion einer prähistorischen Siedlung mit freier Besichtigung.","parentDetails":"Kleine Kinder erkunden die Siedlung mit einer erwachsenen Person.","age":"Familienbesuch; Alter für die Workshops prüfen","schedule":"04.05–26.10.2026 täglich 09–17","price":"Erwachsene CHF 8; Kinderticket CHF 4 (Altersgrenze nicht angegeben)","address":"Place du Tilleul 1, 1544 Gletterens","notes[0]":"Rekonstruierte Häuser und Handwerk. Aktivitäten ohne Anmeldung sind für die Sonntage im September und Oktober angekündigt.","notes[1]":"Zusätzliche Workshops und Vorführungen können extra kosten. Die Eintrittsbedingungen und der Preis für kleine Kinder sind noch nicht bestätigt.","notes[2]":"Die Saison endet am 26. Oktober. Besuche im Winter sind nicht garantiert.","practical.indoor.text":"Rekonstruierte Siedlung unter freiem Himmel","practical.costNote.text":"Erwachsene CHF 8, Kinderticket CHF 4. Das Mindestalter für das kostenpflichtige Ticket ist nicht angegeben.","practical.warnings[0]":"Die Saison endet am 26. Oktober 2026. Workshops können extra kosten.","research.findings[0].field":"Saison und Ticket","research.findings[0].text":"Die Siedlung ist bis 26. Oktober 2026 täglich 09–17 geöffnet. Erwachsene CHF 8, Kinderticket CHF 4.","research.remaining[0]":"Mindestalter für das kostenpflichtige Ticket und Preis/Eintritt für einzelne Workshops bestätigen.","sources[0].label":"Saison, Tarif, Adresse und Format"}},
